### 4.3 Jenkins Pipeline 设计

```groovy
pipeline {
    agent any

    environment {
        ACR_REGISTRY = ""registry.cn-hangzhou.aliyuncs.com""
        ACR_NAMESPACE = ""ai-project""
        PROD_SERVER = ""prod-server-ip""
    }

    stages {
        stage(""Checkout"") {
            steps {
                git branch: ""main"", url: ""http://101.200.136.200:3000/ai/new-ai-proj.git""
            }
        }

        stage(""Build Frontend"") {
            steps {
                dir(""frontend"") {
                    sh ""docker build -f Dockerfile.prod -t ${ACR_REGISTRY}/${ACR_NAMESPACE}/ai-frontend:${BUILD_NUMBER} .""
                }
            }
        }

        stage(""Build Backend"") {
            steps {
                dir(""backend"") {
                    sh ""docker build -f Dockerfile -t ${ACR_REGISTRY}/${ACR_NAMESPACE}/ai-backend:${BUILD_NUMBER} .""
                }
            }
        }

        stage(""Push to ACR"") {
            steps {
                withCredentials([usernamePassword(credentialsId: ""aliyun-acr"", usernameVariable: ""ACR_USER"", passwordVariable: ""ACR_PASS"")]) {
                    sh ""docker login -u ${ACR_USER} -p ${ACR_PASS} ${ACR_REGISTRY}""
                    sh ""docker push ${ACR_REGISTRY}/${ACR_NAMESPACE}/ai-frontend:${BUILD_NUMBER}""
                    sh ""docker push ${ACR_REGISTRY}/${ACR_NAMESPACE}/ai-backend:${BUILD_NUMBER}""
                }
            }
        }

        stage(""Deploy to Production"") {
            steps {
                sshagent([""prod-server-ssh""]) {
                    sh ""ssh ubuntu@${PROD_SERVER} ./deploy.sh ${BUILD_NUMBER}""
                }
            }
        }
    }

    post {
        success {
            echo ""部署成功！""
        }
        failure {
            echo ""部署失败，请检查日志""
        }
    }
}
```

### 4.4 生产服务器部署脚本

```bash
#!/bin/bash
# /home/ubuntu/deploy.sh

BUILD_NUMBER=$1
ACR_REGISTRY=""registry.cn-hangzhou.aliyuncs.com""
ACR_NAMESPACE=""ai-project""

# 登录 ACR
docker login -u xxx -p xxx ${ACR_REGISTRY}

# 拉取新镜像
docker pull ${ACR_REGISTRY}/${ACR_NAMESPACE}/ai-frontend:${BUILD_NUMBER}
docker pull ${ACR_REGISTRY}/${ACR_NAMESPACE}/ai-backend:${BUILD_NUMBER}

# 更新容器
docker-compose -f /home/ubuntu/apps/new-ai-proj/docker-compose.prod.yml up -d

echo ""部署完成: Build #${BUILD_NUMBER}""
```

